const REASON = {
  w: 'Imported inactive (Oct 2026): also a common English word, would fire on English tickets',
  p: 'Imported inactive (Oct 2026): English phrase not on the English list, would fire on English tickets',
  n: 'Imported inactive (Oct 2026): bare number, would fire on amounts, order and ticket numbers'
};

function prepare(t) {
  return String(t == null ? '' : t).normalize('NFC').toLowerCase().trim();
}

const existingEn = new Set($('Check table state').first().json.existing_keys || []);

const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const r = item.json || {};
  const lang = String(r.Language == null ? '' : r.Language).trim().toLowerCase();
  const term = String(r.Term == null ? '' : r.Term).normalize('NFC').trim();
  const tier = String(r.Tier == null ? '' : r.Tier).trim().toUpperCase();
  const category = String(r.Category == null ? '' : r.Category).trim();

  if (!lang || !term) continue;
  if (lang === 'en') continue;
  if (['A', 'B', 'C'].indexOf(tier) === -1) continue;

  const key = prepare(term);
  if (seen.has(lang + '|' + key)) continue;
  seen.add(lang + '|' + key);

  const q = (QUARANTINE[lang] || {})[key];
  const quarantine = !!q && !existingEn.has(key);

  out.push({
    json: {
      keyword: term,
      tier: tier,
      category: category,
      active: !quarantine,
      notes: quarantine ? REASON[q] : null,
      language: lang,
      _quarantine_reason: quarantine ? q : null,
      _kept_as_english_duplicate: !!q && !quarantine
    }
  });
}

if (out.length < 17000) {
  throw new Error('Only ' + out.length + ' rows built - expected about 17,199. Check that the sheet "All languages" was read.');
}

return out;

// === Import summary ===
// Mode: "Run Once for All Items". Counts what Build localized rows produced.
const rows = $input.all().map(i => i.json);
const byLang = {};
let active = 0, inactive = 0, keptEnDup = 0;
const reasons = { w: 0, p: 0, n: 0 };
for (const r of rows) {
  byLang[r.language] = byLang[r.language] || { total: 0, active: 0, inactive: 0 };
  byLang[r.language].total++;
  if (r.active) { active++; byLang[r.language].active++; }
  else { inactive++; byLang[r.language].inactive++; reasons[r._quarantine_reason]++; }
  if (r._kept_as_english_duplicate) keptEnDup++;
}
return [{
  json: {
    rows_built: rows.length,
    active: active,
    inactive: inactive,
    inactive_common_english_word: reasons.w,
    inactive_english_phrase: reasons.p,
    inactive_bare_number: reasons.n,
    kept_active_same_as_english_row: keptEnDup,
    languages: Object.keys(byLang).length,
    by_language: byLang
  }
}];

// === Collect existing rows ===
// Mode: "Run Once for All Items". Input = every row currently in cs_high_risk_keywords.
// Builds the set language|keyword|tier (keyword compared the way the matcher sees it:
// lowercase, punctuation and spacing as one space) so the CSV import can skip rows
// that already exist. Re-running the import therefore never creates duplicates.
// Passes the uploaded CSV on as binary "data".

function prepare(text) {
  return String(text == null ? '' : text).normalize('NFC').toLowerCase()
    .replace(/i\u0307/g, 'i').replace(/[^\p{L}\p{M}\p{N}]+/gu, ' ').trim();
}

const existing = [];
for (const i of $input.all()) {
  const r = i.json || {};
  if (r.keyword == null) continue;
  const lang = String(r.language == null ? '' : r.language).trim().toLowerCase();
  const tier = String(r.tier == null ? '' : r.tier).trim().toUpperCase();
  existing.push(lang + '|' + prepare(r.keyword) + '|' + tier);
}

const trig = $('Upload prepared CSV').first();
const bin = trig.binary || {};
const keys = Object.keys(bin);
if (!keys.length) throw new Error('No file was received from the form.');

return [{ json: { existing_rows: existing.length, existing }, binary: { data: bin[keys[0]] } }];

// === Build rows from CSV ===
// Mode: "Run Once for All Items". Input = one item per CSV row.
// Expected columns: keyword, tier, category, active, notes, language
// (the format of tier_c_import.csv). Any other columns are ignored.
// - tier must be A, B or C; language and keyword must be present
// - active: true/false (also 1/0, yes/no); empty = true
// - rows that already exist (same language, keyword and tier) are skipped,
//   as are duplicates inside the file
// Throws if nothing is left to import, so an accidental re-run is visible.

function prepare(text) {
  return String(text == null ? '' : text).normalize('NFC').toLowerCase()
    .replace(/i\u0307/g, 'i').replace(/[^\p{L}\p{M}\p{N}]+/gu, ' ').trim();
}

const existing = new Set($('Collect existing rows').first().json.existing || []);
const seen = new Set();
const out = [];
let invalid = 0, already = 0, dupInFile = 0;

function parseActive(v) {
  const s = String(v == null ? '' : v).trim().toLowerCase();
  if (s === '' || s === 'true' || s === '1' || s === 'yes') return true;
  if (s === 'false' || s === '0' || s === 'no') return false;
  return null;
}

for (const item of $input.all()) {
  const r = item.json || {};
  const keyword = String(r.keyword == null ? '' : r.keyword).normalize('NFC').trim();
  const tier = String(r.tier == null ? '' : r.tier).trim().toUpperCase();
  const language = String(r.language == null ? '' : r.language).trim().toLowerCase();
  const category = String(r.category == null ? '' : r.category).trim();
  const notesRaw = String(r.notes == null ? '' : r.notes).trim();
  const active = parseActive(r.active);

  if (!keyword || !language || ['A', 'B', 'C'].indexOf(tier) === -1 || active === null || !prepare(keyword)) {
    invalid++;
    continue;
  }
  const key = language + '|' + prepare(keyword) + '|' + tier;
  if (existing.has(key)) { already++; continue; }
  if (seen.has(key)) { dupInFile++; continue; }
  seen.add(key);

  out.push({ json: { keyword, tier, category, active, notes: notesRaw || null, language,
    _stats: { invalid, already, dupInFile } } });
}

if (!out.length) {
  throw new Error('Nothing to import: ' + already + ' rows already exist, ' + dupInFile +
    ' duplicates in the file, ' + invalid + ' invalid rows.');
}
// final counters on every row (the summary reads the last one)
for (const o of out) o.json._stats = { invalid, already, dupInFile };
return out;

// === CSV import summary ===
// Mode: "Run Once for All Items". Counts what Build rows from CSV produced.
const rows = $input.all().map(i => i.json);
const st = rows.length ? rows[rows.length - 1]._stats : {};
const byLang = {}, byTier = {};
let active = 0, inactive = 0;
for (const r of rows) {
  byLang[r.language] = byLang[r.language] || { total: 0, active: 0, inactive: 0 };
  byLang[r.language].total++;
  byTier[r.tier] = (byTier[r.tier] || 0) + 1;
  if (r.active) { active++; byLang[r.language].active++; } else { inactive++; byLang[r.language].inactive++; }
}
return [{ json: {
  rows_in_file: $('Read CSV').all().length,
  rows_inserted: rows.length,
  active, inactive,
  skipped_already_in_table: st.already || 0,
  skipped_duplicate_in_file: st.dupInFile || 0,
  skipped_invalid: st.invalid || 0,
  by_tier: byTier,
  languages: Object.keys(byLang).length,
  by_language: byLang
} }];
